WITH scored AS (SELECT *, NTILE(3) OVER (ORDER BY budget DESC, id ASC) AS budget_bucket, PERCENT_RANK() OVER (PARTITION BY location ORDER BY budget DESC) AS budget_percent_rank, LAG(budget, 2) OVER w_part AS prev_budget, NTILE(3) OVER (PARTITION BY location ORDER BY budget ASC, id ASC) AS budget_bucket_2 FROM departments WINDOW w_part AS (PARTITION BY dept_name, location ORDER BY budget ASC, id ASC)) SELECT id, location, budget, budget_bucket, budget_percent_rank, budget_bucket_2, CASE WHEN location RLIKE '^(New York|Berlin)$' THEN 'GROUP_B' WHEN location RLIKE '^(Bangkok|Chiang Mai)$' THEN 'GROUP_A' ELSE 'CORE' END AS location_zone FROM scored
